python3 -c "
# Verify no global random.seed inside src/sampler
import ast, sys

with open('src/sampler/core.py') as f:
    tree = ast.parse(f.read())

for node in ast.walk(tree):
    if isinstance(node, ast.FunctionDef):
        for child in ast.walk(node):
            if isinstance(child, ast.Call):
                if isinstance(child.func, ast.Name) and child.func.id == 'seed':
                    print(f'ERROR: random.seed() found in function {node.name}')
                    sys.exit(1)

print('OK: No random.seed() found in src/sampler/core.py')
"
